package com.example.planyourtrip.controller;
import com.example.planyourtrip.dto.TripDto; import com.example.planyourtrip.security.AuthUser; import com.example.planyourtrip.service.TripService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/trips") public class TripController { private final TripService service; public TripController(TripService service){this.service=service;} @GetMapping List<TripDto> list(@AuthUser Long uid){return service.list(uid);} @GetMapping("/{id}") TripDto get(@AuthUser Long uid,@PathVariable Long id){return service.get(uid,id);} @PostMapping TripDto create(@AuthUser Long uid,@Valid @RequestBody TripDto d){return service.create(uid,d);} @PutMapping("/{id}") TripDto update(@AuthUser Long uid,@PathVariable Long id,@Valid @RequestBody TripDto d){return service.update(uid,id,d);} @DeleteMapping("/{id}") void delete(@AuthUser Long uid,@PathVariable Long id){service.delete(uid,id);} }
